// Block (composition) — a ready-to-use one-time-code form assembled from Components.
// Contract: docs/rules/block-contract.md. Arranges only (Stack for layout);
// composes Form/PinField/Button/Alert. Owns no Component look; mints no tokens.
import type { FormEvent, Ref } from "react";
import { Form } from "../components/Form";
import { PinField } from "../components/PinField";
import { Button } from "../components/Button";
import { ButtonGroup } from "../components/ButtonGroup";
import { Alert } from "../components/Alert";
import { Stack } from "../layouts/Stack";
import "./OtpVerifyForm.css";

export interface OtpVerifyFormProps {
  /** Heading shown above the fields. */
  heading?: string;
  /** Called with the entered verification code on submit. */
  onSubmit?: (values: { code: string }) => void;
  /** Called when the user requests another verification code. */
  onResend?: () => void;
  /** Form-level error, shown above the fields. */
  errorMessage?: string;
  /** Puts the submit button in a pending state and blocks re-submit. */
  isPending?: boolean;
  className?: string;
  ref?: Ref<HTMLFormElement>;
}

export function OtpVerifyForm({
  heading = "Verify your email",
  onSubmit,
  onResend,
  errorMessage,
  isPending,
  className,
  ref,
}: OtpVerifyFormProps) {
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onSubmit?.({
      code: String(data.get("code") ?? ""),
    });
  };

  return (
    <Form isPending={isPending}
      ref={ref}
      onSubmit={handleSubmit}
      className={className ? `sd-otpverifyform ${className}` : "sd-otpverifyform"}
    >
      <Stack gap="large" className="sd-otpverifyform__content">
        {heading && (
          <>
            <h1 className="sd-otpverifyform__heading sd-type-headline-medium">{heading}</h1>
          </>
        )}
        {/* live="assertive": see `AlertProps.live` — submit failure is the case that earns it. */}
        {errorMessage && (
          <Alert variant="error" live="assertive">
            {errorMessage}
          </Alert>
        )}
        <Stack gap="medium" className="sd-otpverifyform__fields">
          {/* One cell per digit, one real input under them, so a pasted or autofilled code lands whole. */}
          <PinField label="Verification code" name="code" length={6} isRequired />
        </Stack>
        {/* ButtonGroup, not two siblings 20px apart: these are one action group, and its contract
            is that the LAST child is the primary — which is what six of the eight adjacent Button
            pairs in this tier already do. */}
        <ButtonGroup layout="stack">
          <Button size="large" type="button" variant="secondary" onPress={onResend}>
            Resend code
          </Button>
          <Button size="large" type="submit" variant="primary" isPending={isPending}>
            Verify
          </Button>
        </ButtonGroup>
      </Stack>
    </Form>
  );
}

/* OtpVerifyForm.css — .sd-otpverifyform (Block)
   Arrangement only: fills the column it is given; the page sets that column on the grid
   (a Container span or a LayoutGrid item), never this Block.
   Component look is owned by Form/TextField/Button/Alert; grouping is via Stack.
   No new tokens. */
.sd-otpverifyform {
  width: 100%;
}

.sd-otpverifyform__heading {
  margin: 0;
}
